<?php
/**
 * Carosello notizie sotto l'hero.
 * Visibile solo se sono selezionati articoli manuali in homepage (stessa condizione di slider-notizie).
 *
 * @package Design_Scuole_Italia
 */
global $post;

$home_articoli_manuali = dsi_get_option( 'home_articoli_manuali', 'homepage' );

if ( ! is_array( $home_articoli_manuali ) || ! count( $home_articoli_manuali ) ) {
	return;
}
?>
<style>
  .section-carousel-after-hero {
    padding-top: 1.5rem;
    padding-bottom: 1.5rem;
  }

  .section-carousel-after-hero .home-carousel.it-carousel-wrapper {
    background-color: #fff !important;
    box-shadow: 0 2px 20px 0 rgba(0, 0, 0, 0.1);
    border-radius: 4px;
    overflow: hidden;
  }

  .section-carousel-after-hero .home-carousel .it-single-slide-wrapper a.read-more:before {
    position: initial !important;
    float: right !important;
  }

  .section-carousel-after-hero .home-carousel .splide__track,
  .section-carousel-after-hero .home-carousel .splide__slide {
    padding: 0px !important;
  }

  .section-carousel-after-hero .home-carousel .splide__slide .banner {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 90px;
  }

  .section-carousel-after-hero .home-carousel .splide__slide .banner img {
    max-height: 90px;
    height: auto;
  }

  .section-carousel-after-hero .home-carousel.it-carousel-wrapper.it-carousel-landscape-abstract .splide__pagination {
    margin-bottom: 5px !important;
  }
</style>
<section class="section bg-white section-carousel-after-hero">
  <div class="container">
    <div class="row variable-gutters">
      <div class="col-md-12 mb-4 mt-4">
        <div class="it-carousel-wrapper home-carousel it-carousel-landscape-abstract splide"
          data-splide='{"type":"slide","perPage":1,"arrows":true,"pagination":true,"autoplay":true,"rewind":true}'>
          <div class="splide__track ps-lg-3 pe-lg-3">
            <ul class="splide__list it-carousel-all">
              <?php
              foreach ( $home_articoli_manuali as $articolo_id ) :
                $post = get_post( $articolo_id );
                if ( ! $post ) {
                  continue;
                }
                setup_postdata( $post );

                $image_url          = get_the_post_thumbnail_url( $post, 'large' );
                $data_pubblicazione = get_the_date( 'd/m/Y', $post );
                $titolo             = get_the_title( $post );
                $link               = get_permalink( $post );

                if ( $post->post_type === 'post' ) {
                  $descrizione = $post->_dsi_articolo_descrizione;
                } elseif ( $post->post_type === 'circolare' ) {
                  $descrizione = $post->_dsi_circolare_descrizione;
                } else {
                  $descrizione = get_the_excerpt( $post );
                }

                $autore = get_the_author_meta( 'display_name', $post->post_author );
                ?>
              <li class="splide__slide">
                <div class="it-single-slide-wrapper">
                  <a href="<?php echo esc_url( $link ); ?>" title="<?php echo esc_attr( $titolo ); ?>">
